/**
 * Clears the assignee on every live issue held by `userId` and returns the
 * issues it touched. Archived issues keep their assignee.
 */
export async function clearAssigneeForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .update(issues)
    .set({ assigneeId: null, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, userId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning()
    .all();

  return rows.map((row) => toIssue(row));
}

